import { useEffect, useState } from "react";
import { Navigate } from "react-router-dom";
import { toast } from "sonner";
import { Plus, Trash2, Package, DollarSign, ShoppingBag, Store } from "lucide-react";
import { api, errMsg, money } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";

const STATUS = { pending: "Aguardando", processing: "Preparando", shipped: "Enviado", delivered: "Entregue", canceled: "Cancelado" };

export default function SellerDashboard() {
  const { user } = useAuth();
  const [tab, setTab] = useState("products");
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const load = async () => {
    try {
      const [p, o] = await Promise.all([api.get("/mp/seller/products"), api.get("/mp/seller/orders")]);
      setProducts(p.data); setOrders(o.data);
    } catch (e) { toast.error(errMsg(e)); }
  };
  useEffect(() => { if (user && user.user_type === "seller") load(); }, [user]);

  if (user === false) return <Navigate to="/login?next=/seller" replace />;
  if (user && user.user_type !== "seller") return <Navigate to="/" replace />;

  const revenue = orders.filter((o) => o.status !== "canceled").reduce((s, o) => s + o.amount, 0);
  const pending = orders.filter((o) => o.status === "pending").length;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10" data-testid="seller-dashboard">
      <div className="flex items-center gap-3">
        <span className="grid h-12 w-12 place-items-center rounded-xl bg-brand-500 text-white">
          <Store className="h-5 w-5" />
        </span>
        <div>
          <h1 className="font-display text-2xl font-extrabold">{user?.store_name}</h1>
          <p className="text-sm text-ink-500">Painel do vendedor</p>
        </div>
      </div>

      <div className="mt-8 grid gap-4 sm:grid-cols-3">
        <StatCard icon={Package} label="Produtos" value={products.length} />
        <StatCard icon={ShoppingBag} label="Pedidos pendentes" value={pending} />
        <StatCard icon={DollarSign} label="Receita bruta" value={money(revenue)} />
      </div>

      <div className="mt-8 flex gap-2 border-b border-black/10">
        <TabBtn active={tab === "products"} onClick={() => setTab("products")} testId="tab-products">Produtos</TabBtn>
        <TabBtn active={tab === "orders"} onClick={() => setTab("orders")} testId="tab-orders">Pedidos</TabBtn>
      </div>

      {tab === "products" && <ProductsTab products={products} reload={load} />}
      {tab === "orders" && <OrdersTab orders={orders} reload={load} />}
    </div>
  );
}

function StatCard({ icon: Icon, label, value }) {
  return (
    <div className="rounded-2xl border border-black/5 bg-white p-5">
      <div className="flex items-center justify-between"><Icon className="h-4 w-4 text-brand-500" /></div>
      <p className="mt-3 text-xs uppercase text-ink-500">{label}</p>
      <p className="mt-1 font-display text-3xl font-extrabold">{value}</p>
    </div>
  );
}

function TabBtn({ active, onClick, children, testId }) {
  return (
    <button onClick={onClick} data-testid={testId}
            className={`border-b-2 px-3 py-2 text-sm font-medium ${active ? "border-brand-500 text-brand-600" : "border-transparent text-ink-500"}`}>
      {children}
    </button>
  );
}

function ProductsTab({ products, reload }) {
  const empty = { name: "", description: "", price_cents: 0, currency: "BRL", image_url: "", stock: 1, category: "" };
  const [form, setForm] = useState(empty);
  const [saving, setSaving] = useState(false);
  const create = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await api.post("/mp/seller/products", { ...form, price_cents: Number(form.price_cents), stock: Number(form.stock) });
      toast.success("Produto publicado"); setForm(empty); reload();
    } catch (err) { toast.error(errMsg(err)); }
    finally { setSaving(false); }
  };
  const remove = async (id) => {
    if (!window.confirm("Excluir produto?")) return;
    try { await api.delete(`/mp/seller/products/${id}`); reload(); }
    catch (e) { toast.error(errMsg(e)); }
  };
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });
  return (
    <div className="mt-6 grid gap-8 lg:grid-cols-[380px,1fr]">
      <form onSubmit={create} className="h-fit rounded-2xl border border-black/5 bg-white p-5" data-testid="new-product-form">
        <h3 className="flex items-center gap-2 font-display text-base font-bold">
          <Plus className="h-4 w-4 text-brand-500" /> Novo produto
        </h3>
        <div className="mt-4 space-y-3">
          <div><label className="text-xs">Nome</label>
            <input required value={form.name} onChange={set("name")} data-testid="prod-name"
                   className="mt-1 h-10 w-full rounded-lg border border-black/10 px-3 text-sm outline-none focus:border-brand-500" /></div>
          <div><label className="text-xs">Descrição</label>
            <textarea rows="3" value={form.description} onChange={set("description")} data-testid="prod-desc"
                   className="mt-1 w-full rounded-lg border border-black/10 p-3 text-sm outline-none focus:border-brand-500" /></div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="text-xs">Preço (centavos)</label>
              <input type="number" required min="1" value={form.price_cents} onChange={set("price_cents")} data-testid="prod-price"
                     className="mt-1 h-10 w-full rounded-lg border border-black/10 px-3 text-sm outline-none focus:border-brand-500" /></div>
            <div><label className="text-xs">Estoque</label>
              <input type="number" required min="0" value={form.stock} onChange={set("stock")} data-testid="prod-stock"
                     className="mt-1 h-10 w-full rounded-lg border border-black/10 px-3 text-sm outline-none focus:border-brand-500" /></div>
          </div>
          <div><label className="text-xs">Categoria</label>
            <input value={form.category} onChange={set("category")} placeholder="Ex: Casa, Moda"
                   className="mt-1 h-10 w-full rounded-lg border border-black/10 px-3 text-sm outline-none focus:border-brand-500" /></div>
          <div><label className="text-xs">URL da imagem</label>
            <input value={form.image_url} onChange={set("image_url")} placeholder="https://…"
                   className="mt-1 h-10 w-full rounded-lg border border-black/10 px-3 text-sm outline-none focus:border-brand-500" /></div>
          <button type="submit" disabled={saving} data-testid="prod-submit"
                  className="w-full rounded-full bg-brand-500 px-4 py-2.5 text-sm font-semibold text-white hover:bg-brand-600">
            {saving ? "Publicando…" : "Publicar produto"}
          </button>
        </div>
      </form>
      <div className="space-y-3">
        {products.length === 0 ? (
          <p className="rounded-2xl border border-dashed border-black/10 p-8 text-center text-sm text-ink-500">
            Nenhum produto ainda. Publique o primeiro à esquerda.
          </p>
        ) : products.map((p) => (
          <div key={p.id} className="flex items-center gap-4 rounded-2xl border border-black/5 bg-white p-4" data-testid={`sp-${p.id}`}>
            <div className="h-16 w-16 shrink-0 overflow-hidden rounded-lg bg-brand-50">
              {p.image_url && <img src={p.image_url} alt={p.name} className="h-full w-full object-cover" />}
            </div>
            <div className="min-w-0 flex-1">
              <p className="line-clamp-1 font-medium">{p.name}</p>
              <p className="text-xs text-ink-500">Estoque: {p.stock}</p>
            </div>
            <p className="font-display font-extrabold text-brand-600">{money(p.price_cents, p.currency)}</p>
            <button onClick={() => remove(p.id)} className="grid h-9 w-9 place-items-center text-red-500 hover:bg-red-50 rounded-full"
                    data-testid={`sp-del-${p.id}`}>
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

function OrdersTab({ orders, reload }) {
  const setStatus = async (id, status) => {
    try { await api.patch(`/mp/seller/orders/${id}?status=${status}`); reload(); toast.success("Status atualizado"); }
    catch (e) { toast.error(errMsg(e)); }
  };
  if (orders.length === 0)
    return <p className="mt-6 rounded-2xl border border-dashed border-black/10 p-8 text-center text-sm text-ink-500">Sem pedidos ainda.</p>;
  return (
    <div className="mt-6 space-y-3">
      {orders.map((o) => (
        <div key={o.id} className="rounded-2xl border border-black/5 bg-white p-5" data-testid={`sorder-${o.id}`}>
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-ink-500">#{o.id.slice(-8)} · {new Date(o.created_at).toLocaleString("pt-BR")}</p>
              <p className="mt-1 font-medium">{o.buyer_name} — {o.buyer_email}</p>
              <p className="text-xs text-ink-500">{o.shipping_address} · {o.phone}</p>
            </div>
            <select value={o.status} onChange={(e) => setStatus(o.id, e.target.value)}
                    className="rounded-full border border-black/10 bg-white px-3 py-1 text-sm"
                    data-testid={`sorder-status-${o.id}`}>
              {Object.entries(STATUS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select>
          </div>
          <ul className="mt-3 divide-y divide-black/5 text-sm">
            {o.items.map((it, i) => (
              <li key={i} className="flex justify-between py-2">
                <span>{it.quantity}× {it.name}</span>
                <span className="font-medium">{money(it.line_total_cents, o.currency)}</span>
              </li>
            ))}
          </ul>
          <div className="mt-2 flex justify-between border-t border-black/5 pt-3">
            <span className="text-xs text-ink-500">Total</span>
            <span className="font-display text-lg font-extrabold text-brand-600">{money(o.amount, o.currency)}</span>
          </div>
        </div>
      ))}
    </div>
  );
}
